def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full separator lines divide the grid into independent panels.
    row_seps = [r for r in range(h) if len(set(grid[r])) == 1]
    col_seps = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    rb = [-1] + row_seps + [h]
    cb = [-1] + col_seps + [w]

    # The most common non-separator color is the panel background;
    # the less common nonzero color marks cells of interest.
    counts = {}
    for r in range(h):
        for c in range(w):
            if r not in row_seps and c not in col_seps:
                v = grid[r][c]
                counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    marker = min(counts, key=counts.get)

    out = []
    for i in range(len(rb) - 1):
        outrow = []
        for j in range(len(cb) - 1):
            cells = [
                grid[r][c]
                for r in range(rb[i] + 1, rb[i + 1])
                for c in range(cb[j] + 1, cb[j + 1])
            ]
            n = sum(v == marker for v in cells)
            outrow.append(1 if n == 2 else background)
        out.append(outrow)
    return out
